"""Compare only server-calculated purchase alternatives, not a new evaluator."""
CSS='''
.po-alternatives-table{margin:16px 0;padding:14px;background:#f4f8ff;border:1px solid #bfd2ed;border-radius:8px}.po-alternatives-table h3{font-size:16px!important;margin:0 0 10px}.po-alternatives-table p{font-size:13px;line-height:1.5}.po-alternatives-table .scroll{overflow:auto}.po-alternatives-table table{min-width:1040px;width:100%;border-collapse:collapse}.po-alternatives-table th,.po-alternatives-table td{padding:10px;text-align:left;vertical-align:top;border-bottom:1px solid #cad9ef;font-size:13px}.po-alternatives-table thead{background:#dfeaff}.po-alternatives-table td:first-child{min-width:210px}.po-alternatives-table .po-money-saving{color:#16632c;font-weight:bold}.po-alternatives-table .po-money-cost{color:#99281f;font-weight:bold}.po-alternatives-table tr[data-baseline]{background:#eaf1fb}.po-alternatives-table details{max-width:310px;white-space:normal}.po-alternatives-table button{white-space:normal}
'''
JS=r'''
(function purchaseAlternativesTable(){
 const live=document.createElement('section');live.id='po-alternatives-table';live.className='po-alternatives-table';live.setAttribute('aria-label','Comparación de alternativas calculadas');$('po-conditions').querySelector('.po-negotiation-scroll').after(live);
 function note(box,text){const p=document.createElement('p');p.textContent=text;box.append(p)}
 function table(box,r,editable){box.replaceChildren();const title=document.createElement('h3');title.textContent=editable?'COMPARAR ALTERNATIVAS CALCULADAS':'ALTERNATIVAS DEL ESTUDIO GUARDADO';box.append(title);
  if(!r?.scenario||!r.current_terms||!r.analysis_fingerprint){note(box,!editable&&!r?.current_terms?'Este estudio anterior no conserva el detalle de esta tabla. Consulta sus resultados guardados; no se reconstruyen con datos actuales.':r?.message||'Completa las condiciones para calcular alternativas. Los resultados anteriores se retiran al cambiar datos.');return}
  note(box,'Propuesta activa y alternativas para el mismo expediente. Importes completos con IVA y portes; el ahorro se compara con la propuesta activa de esta tabla.');
  const scroll=document.createElement('div');scroll.className='scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Alternativas calculadas; desplaza horizontalmente para ver todas las columnas');const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');for(const text of ['Condición y fundamento','Cantidad','Neto por unidad','Total con IVA y portes','Ahorro','Saldo mínimo','Vencimiento de mercancía','Acción']){const th=document.createElement('th');th.scope='col';th.textContent=text;tr.append(th)}head.append(tr);table.append(head);const body=document.createElement('tbody');
  function row(a,baseline=false){const tr=document.createElement('tr');if(baseline)tr.dataset.baseline='true';else tr.dataset.alternativeKind=a.kind;const cell=text=>{const td=document.createElement('td');td.textContent=text;tr.append(td);return td};
   const label=cell(baseline?'Propuesta activa · referencia de comparación':a.title);if(!baseline){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Fundamento, fuente y pagos';details.append(summary);note(details,a.basis||'Hipótesis para negociar.');if(a.source)note(details,'Fuente: '+(a.source.invoice_number||a.source.flow_ids?.join(', ')||'Hipótesis interna')+' · '+stockDate(a.source.issue_date||a.source.collection_date));note(details,a.stock_effect==='SAME_QUANTITY'?'Mantiene la cantidad.':'Modifica la cantidad; la necesidad depende de los datos y supuestos de stock.');note(details,'Aceptación del proveedor: no confirmada.');for(const p of a.payments||[])note(details,stockDate(p.due_date)+' · '+money(p.amount)+' EUR');label.append(details)}
   cell(a.quantity!==undefined?stockNumber(a.quantity)+' '+(a.unit||r.current_terms.unit):'Sin dato');cell(a.net_unit_price!==undefined?money(a.net_unit_price)+' EUR':'Sin dato');cell(money(a.total)+' EUR');const saving=cell(baseline?'—':money(a.savings)+' EUR');if(!baseline)saving.className=Number(a.savings)>0?'po-money-saving':Number(a.savings)<0?'po-money-cost':'';
   cell(money(a.minimum_balance)+' EUR · '+stockDate(a.minimum_date));cell(stockDate(a.due_date));const action=cell(baseline?'Base del cálculo':editable?'':'Consulta del estudio guardado');if(!baseline&&editable){const button=document.createElement('button');button.type='button';button.textContent='Usar en Mi propuesta';button.onclick=()=>{if(typeof applyPurchaseSuggestedAlternative==='function')applyPurchaseSuggestedAlternative(a)};action.append(button)}body.append(tr);
  }
  row(r.current_terms,true);for(const a of r.alternatives||[])row(a);table.append(body);scroll.append(table);box.append(scroll);if(!r.alternatives?.length)note(box,'No se ha encontrado otra condición justificable con los datos actuales. Consulta las comprobaciones de stock y las limitaciones del análisis.');note(box,'Sin ganadora automática. Aplicar prepara una hipótesis; guardar conserva el estudio y no confirma una compra.');const trace=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Identificación del estudio';trace.append(summary);note(trace,'Corte: '+stockDate(r.cutoff)+' · Horizonte: '+stockDate(r.horizon_end)+' · Huella: '+r.analysis_fingerprint);box.append(trace);
 }
 window.clearPurchaseAlternativesTable=()=>{live.replaceChildren();const h=document.createElement('h3');h.textContent='COMPARAR ALTERNATIVAS CALCULADAS';live.append(h);note(live,'Recalculando con los datos actuales…');};
 window.renderPurchaseAlternativesTable=r=>table(live,r,true);
 window.renderSavedPurchaseAlternativesTable=(parent,r)=>{const box=document.createElement('section');box.className='po-alternatives-table';table(box,r,false);parent.append(box)};
 clearPurchaseAlternativesTable();
})();
'''
